function toast(message){$('#toast').textContent=message;$('#toast').classList.add('visible');setTimeout(()=>$('#toast').classList.remove('visible'),4500)}
async function api(path,method='GET',body){const r=await fetch(path,{method,headers:{'Content-Type':'application/json','X-Relay-Client':'dashboard','X-Relay-CSRF':csrf},...(body?{body:JSON.stringify(body)}:{})});let d=await r.json().catch(()=>({detail:'Unexpected server response.'}));if(!r.ok){if(r.status===401&&user){user=null;csrf='';modal.close();await boot()}throw new Error(typeof d.detail==='string'?d.detail:JSON.stringify(d.detail))}return d}
function authScreen(setup){app.innerHTML=`<div class="auth"><section class="auth-art"><a class="brand" href="/">${mark}relay<span>.</span></a><div><p class="eyebrow">AUTONOMY, WITH INTENTION</p><h1>Every big action.<br>A <em>human moment.</em></h1><p>A quiet checkpoint between what your agents propose and what actually happens.</p></div><div class="orbital" aria-hidden="true"><span class="center">↗</span><i class="spark"></i></div><div class="footer"><span>BUILT ON ORBIT’S APPROVAL CORE</span><span>01 / RELAY</span></div></section><section class="auth-form"><div><p class="eyebrow">YOUR LOCAL WORKSPACE</p><h2>${setup?'Make room for oversight.':'Welcome back.'}</h2><p>${setup?'Create your private workspace. You will review and approve the actions your agents send here.':'Sign in to review requests and keep your agents moving.'}</p><form id="auth-form"><label class="field">Username<input name="username" autocomplete="username" minlength="3" maxlength="50" pattern="[a-zA-Z0-9_.-]+" required></label><label class="field">Password<input name="password" type="password" autocomplete="${setup?'new-password':'current-password'}" minlength="12" maxlength="128" required></label><p class="hint">At least 12 characters. No default credentials.</p><div class="error" id="auth-error" role="alert"></div><button class="btn" type="submit">${setup?'Create workspace':'Sign in'} <span>↗</span></button></form><p class="hint">Runs on your machine. Agent API keys cannot approve actions.</p></div></section></div>`;$('#auth-form').onsubmit=async e=>{e.preventDefault();let b=e.target.querySelector('button');b.disabled=true;try{let f=new FormData(e.target),r=await api(setup?'/api/setup':'/api/login','POST',Object.fromEntries(f));user=r.username;csrf=r.csrf;await refresh();shell()}catch(err){$('#auth-error').textContent=err.message}finally{b.disabled=false}}}
async function boot(){try{let s=await api('/api/status');if(s.setup_required){authScreen(true);return}try{let u=await api('/api/me');user=u.username;csrf=u.csrf;await refresh();shell()}catch{authScreen(false)}}catch(e){app.innerHTML=`<div class="empty"><h3>Relay is taking a moment.</h3><p>${esc(e.message)}</p><button class="btn" id="reload">Try again</button></div>`;$('#reload').onclick=boot}}
async function refresh(){[actions,agentList,health]=await Promise.all([api('/api/actions'),api('/api/agents'),api('/api/health')])}
function shell(){app.innerHTML=`<div class="layout"><aside class="sidebar"><a class="brand" href="/">${mark}relay<span>.</span></a><p class="workspace">WORKSPACE / PERSONAL</p><nav>${Object.entries(names).map(([id,n],i)=>`<button data-nav="${id}" class="${page===id?'active':''}"><b aria-hidden="true">${['▤','⌘','◇','↗','⊕'][i]}</b>${n}${id==='inbox'?`<span class="count">${actions.filter(a=>a.status==='pending').length}</span>`:''}</button>`).join('')}</nav><div class="side-bottom"><div class="side-note">Agents do the work.<br>You keep the say.</div><div class="user"><span class="avatar">${esc(user.slice(0,2).toUpperCase())}</span><div>${esc(user)}<small>Workspace owner</small></div><button class="logout" id="logout" title="Sign out" aria-label="Sign out">↗</button></div></div></aside><main class="main"><header class="topbar"><div class="crumb">Workspace<span>/</span>${names[page]}</div><div class="system"><i class="dot ${health.worker_online?'':'off'}"></i>${health.worker_online?'Worker online':'Worker offline'}</div></header><div class="content" id="content"></div></main></div>`;document.querySelectorAll('[data-nav]').forEach(b=>b.onclick=()=>{page=b.dataset.nav;query='';shell()});$('#logout').onclick=async()=>{await api('/api/logout','POST');user=null;csrf='';authScreen(false)};renderPage()}
function heading(k,title,sub,button=''){return `<div class="hero"><div><p class="eyebrow">${k}</p><h1>${title}</h1><p>${sub}</p>${button}</div><div class="orbital" aria-hidden="true"><span class="center">↗</span><i class="spark"></i></div></div>`}
function renderPage(){const c=$('#content');if(page==='inbox'){const pending=actions.filter(a=>a.status==='pending').length; c.innerHTML=heading('THE HUMAN CHECKPOINT','A little pause.<br><em>A better outcome.</em>','Your agents are ready to act. Give the important moments your attention.',`<div class="hero-actions"><button class="btn" id="sample">Try a sample request <span>↗</span></button><button class="text-button" data-go="connect">Connect your agent →</button></div>`)+`<div class="metrics"><div class="metric"><label>Needs your review</label><strong>${String(pending).padStart(2,'0')}</strong><small>WAITING</small></div><div class="metric"><label>Delivered</label><strong>${String(actions.filter(a=>a.status==='succeeded').length).padStart(2,'0')}</strong></div><div class="metric"><label>Stopped safely</label><strong>${String(actions.filter(a=>['rejected','blocked','expired'].includes(a.status)).length).padStart(2,'0')}</strong></div><div class="metric"><label>Connected agents</label><strong>${String(agentList.filter(a=>a.active).length).padStart(2,'0')}</strong></div></div><div class="section-head"><h2>The decision desk</h2><input class="search" id="search" aria-label="Search requests" placeholder="Search requests…" value="${esc(query)}"></div><div class="tabs">${[['pending','Needs review'],['all','All requests'],['succeeded','Delivered'],['stopped','Stopped']].map(([id,n])=>`<button data-filter="${id}" class="${filter===id?'active':''}">${n}</button>`).join('')}</div><div id="requests"></div><div class="process"><div><label>01 / PROPOSE</label><h3>An agent asks.</h3><p>Exact action. Clear intent.<br>No hidden side effects.</p></div><div><label>02 / CONSIDER</label><h3>You make the call.</h3><p>Review the content.<br>Approve it or stop it.</p></div><div><label>03 / DELIVER</label><h3>Relay follows through.</h3><p>One approved execution.<br>A record of every step.</p></div></div><div class="footer"><span>YOUR ATTENTION IS THE PERMISSION.</span><span>LOCAL GATEWAY / V1.0</span></div>`;$('#sample').onclick=sample;$('#search').oninput=e=>{query=e.target.value;rows()};document.querySelectorAll('[data-filter]').forEach(b=>b.onclick=()=>{filter=b.dataset.filter;renderPage()});rows()}
else if(page==='agents'){c.innerHTML=heading('THE PEOPLE BEHIND THE AGENTS','Meet your<br><em>working partners.</em>','Give each agent its own key and only the tools it needs.',`<div class="hero-actions"><button class="btn" id="add-agent">Connect an agent +</button></div>`)+`<div class="section-head"><h2>Your connections</h2><small>KEYS ARE SHOWN ONCE</small></div>`+(agentList.length?agentList.map(a=>`<div class="agent-row"><span class="tool-icon">⌘</span><div><h3>${esc(a.name)}</h3><p>${esc(JSON.parse(a.tools).join(' · '))}</p><p>${esc(a.prefix)}… · ${stamp(a.created)}</p></div>${badge(a.active?'active':'revoked')}${a.active?`<button class="btn light" data-revoke="${a.id}">Revoke key</button>`:''}</div>`).join(''):'<div class="empty"><h3>Your first connection starts here.</h3><p>Create a scoped API key, then send a proposal from any agent framework.</p></div>');$('#add-agent').onclick=agentDialog;document.querySelectorAll('[data-revoke]').forEach(b=>b.onclick=()=>revokeDialog(b.dataset.revoke))}
else if(page==='policies'){c.innerHTML=heading('PERMISSION BY DESIGN','Clear boundaries.<br><em>Confident agents.</em>','A small, explicit policy surface. External writes always need your approval.')+`<div class="section-head"><h2>Active rules</h2><small>ENFORCED ON THE SERVER</small></div>${[['01','Create a file','Only new .md, .txt, .csv and .json files, inside the action’s own output folder.','pending','Human review'],['02','Send a webhook','Exact JSON to your configured public HTTPS destination. No redirects.','pending','Human review'],['03','Record a log event','Store a short internal message. No network or filesystem tool execution.','succeeded','Auto-allow'],['04','Everything else','Shell commands, deletion, arbitrary tools and private-network destinations are unavailable.','blocked','Blocked']].map(([n,t,d,s,l])=>`<div class="policy-row"><span class="eyebrow">${n}</span><div><h3>${t}</h3><p>${d}</p></div><span class="badge ${s}">${l}</span></div>`).join('')}<div class="notice">Approvals are tied to the exact payload. They expire, cannot be reused, and can only be issued by the workspace owner. Agents cannot approve their own requests.</div>`}
else if(page==='activity'){c.innerHTML=heading('EVERY STEP, ACCOUNTED FOR','A trail you<br><em>can follow.</em>','Submissions, decisions and execution outcomes, in one place.')+'<div id="events"><p class="hint">Loading activity…</p></div>';api('/api/audit').then(events=>{if(page!=='activity')return;$('#events').innerHTML=events.length?events.map(e=>`<div class="timeline-entry"><span class="time">${stamp(e.at)}</span><div>${badge(e.kind)}<p>${esc(e.message)}</p></div></div>`).join(''):'<div class="empty"><h3>A clean slate.</h3><p>Your agent activity will appear here.</p></div>'}).catch(e=>toast(e.message))}
else if(page==='connect'){c.innerHTML=heading('FROM ANY AGENT TO YOUR INBOX','One connection.<br><em>You stay in control.</em>','Use a scoped API key to send proposals from Python, a workflow, or your own agent.')+`<div class="connection-grid"><section><h2>Send your first proposal</h2><p class="hint">Create a key in Connected agents. Store it as RELAY_API_KEY in your environment.</p><pre class="code">${esc(`import os, requests, uuid\n\nresponse = requests.post(\n    "http://127.0.0.1:8080/v1/actions",\n    headers={"Authorization":\n        "Bearer " + os.environ["RELAY_API_KEY"]},\n    json={\n        "title": "Save my research report",\n        "reason": "Ready for your review",\n        "tool": "save_file",\n        "arguments": {\n            "filename": "report.md",\n            "content": "# My reviewed report"\n        },\n        "idempotency_key": str(uuid.uuid4())\n    }, timeout=15\n)\nresponse.raise_for_status()\nprint(response.json())`)}</pre><p class="hint">Poll GET /v1/actions/{id} with the same key for the result. Reuse the same idempotency key when retrying the same request.</p><a href="/docs" target="_blank" rel="noopener" class="text-button">Explore the API documentation ↗</a></section><section><h2>Webhook destination</h2><p class="hint">Connect n8n, Make, or another HTTPS endpoint. Agents can propose a payload, but only you choose the destination.</p><div id="connection-state" class="notice">Checking connection…</div><form id="connection-form"><label class="field">Secret webhook URL<input name="url" type="password" placeholder="https://…" autocomplete="off" maxlength="2048" required></label><p class="hint">Stored locally in SQLite, not encrypted at rest. Leave secrets out of shared screenshots. Each proposed destination is visible during review.</p><button class="btn">Save destination</button><button type="button" class="btn light" id="disconnect">Disconnect</button></form><div class="notice">Changing a destination blocks its waiting proposals. A request already in flight cannot be recalled.</div></section></div>`;connectionState();$('#connection-form').onsubmit=async e=>{e.preventDefault();try{await api('/api/connection','PUT',{url:e.target.url.value});e.target.reset();connectionState();toast('Destination saved. No webhook was sent.')}catch(err){toast(err.message)}};$('#disconnect').onclick=async()=>{try{await api('/api/connection','PUT',{url:''});connectionState();toast('Disconnected')}catch(e){toast(e.message)}}}
document.querySelectorAll('[data-go]').forEach(b=>b.onclick=()=>{page=b.dataset.go;shell()})}
async function connectionState(){let d=await api('/api/connection');if($('#connection-state'))$('#connection-state').textContent=d.configured?'Connected to '+d.hostname:'No destination connected.'}
function rows(){const list=actions.filter(a=>(filter==='all'||filter==='stopped'&&['rejected','expired','blocked','unknown'].includes(a.status)||a.status===filter)&&(a.title+' '+a.agent_name).toLowerCase().includes(query.toLowerCase()));$('#requests').innerHTML=list.length?list.map(a=>`<button class="row" data-action="${a.id}"><span class="tool-icon">${a.tool==='save_file'?'▤':a.tool==='send_webhook'?'↗':'≋'}</span><span><strong>${esc(a.title)}</strong><small>${a.tool==='save_file'?'Create a file':a.tool==='send_webhook'?'Send a webhook':'Internal log'} · ${esc(a.arguments.filename||'Exact payload')}</small></span><span class="agent-name">${esc(a.agent_name)}</span>${badge(a.status)}<span class="time">${ago(a.created)}</span><span class="arrow">↗</span></button>`).join(''):`<div class="empty"><span class="tool-icon" style="margin:auto">✓</span><h3>${filter==='pending'?'Nothing needs your attention.':'No requests here yet.'}</h3><p>${filter==='pending'?'When an agent proposes an important action, it will wait here for your decision.':'Try a sample request or connect your own agent.'}</p></div>`;document.querySelectorAll('[data-action]').forEach(b=>b.onclick=()=>actionDialog(b.dataset.action))}
function openDialog(title,eyebrow,body,buttons=''){lastOpener=document.activeElement;modal.innerHTML=`<div class="modal-head"><div><p class="eyebrow">${eyebrow}</p><h2 id="modal-title">${esc(title)}</h2></div><button class="close" aria-label="Close dialog">×</button></div><div class="modal-body">${body}</div>${buttons?`<div class="modal-actions">${buttons}</div>`:''}`;modal.querySelector('.close').onclick=()=>modal.close();if(!modal.open)modal.showModal()}
modal.addEventListener('close',()=>lastOpener?.focus());
async function sample(){try{let a=await api('/api/demo','POST');await refresh();filter='pending';shell();await actionDialog(a.id)}catch(e){toast(e.message)}}
async function actionDialog(id){try{let a=await api('/api/actions/'+id),pending=a.status==='pending',isFile=a.tool==='save_file';openDialog(a.title,`ACTION REVIEW / ${a.tool.replaceAll('_',' ')}`,`${badge(a.status)}<p>${esc(a.reason)}</p><div class="hint">From ${esc(a.agent_name)} · ${stamp(a.created)}<br>Approval expires ${stamp(a.expires)}</div><h3>${isFile?'File / '+esc(a.arguments.filename):'Exact action payload'}</h3><pre class="preview">${esc(isFile?a.arguments.content:JSON.stringify(a.arguments,null,2))}</pre><p class="digest">PAYLOAD SHA-256<br>${esc(a.digest)}</p>${a.error?`<div class="notice">${esc(a.error)}</div>`:''}${a.result?`<h3>Execution result</h3><pre class="preview">${esc(JSON.stringify(a.result,null,2))}</pre>`:''}${pending?'<label class="field">Decision note <span class="hint">(optional)</span><textarea id="decision-note" maxlength="1000" placeholder="Add context for the audit trail…"></textarea></label><label class="hint"><input type="checkbox" id="reviewed"> I reviewed the exact content and destination above.</label>':''}<h3>Action timeline</h3>${a.events.map(e=>`<div class="event"><b>${esc(e.message)}</b><small>${stamp(e.at)}</small></div>`).join('')}`,pending?'<button class="btn danger" id="reject">Reject action</button><button class="btn" id="approve" disabled>Approve & execute ↗</button>':`<button class="btn light" id="refresh-action">Refresh status</button>${isFile&&a.status==='succeeded'?`<a class="btn" href="/api/actions/${a.id}/artifact">Download file ↓</a>`:''}`);if(pending){$('#reviewed').onchange=e=>$('#approve').disabled=!e.target.checked;const decide=async approved=>{let note=$('#decision-note').value;$('#approve').disabled=$('#reject').disabled=true;try{await api('/api/actions/'+id+'/decision','POST',{approved,digest:a.digest,note});await refresh();shell();await actionDialog(id);toast(approved?'Approved. Worker will execute this exact action.':'Rejected. No action will be taken.')}catch(e){toast(e.message);await actionDialog(id)}};$('#approve').onclick=()=>decide(true);$('#reject').onclick=()=>decide(false)}else $('#refresh-action').onclick=()=>actionDialog(id)}catch(e){toast(e.message)}}
function agentDialog(){openDialog('A new working partner.','CONNECT AN AGENT','<form id="agent-form"><label class="field">Agent name<input name="name" required minlength="2" maxlength="60" placeholder="Research assistant"></label><p class="hint">Choose only the tools this agent needs.</p><div class="checks"><label><input type="checkbox" name="tool" value="save_file" checked> Create files</label><label><input type="checkbox" name="tool" value="send_webhook"> Send webhooks</label><label><input type="checkbox" name="tool" value="log_event"> Record logs</label></div><button class="btn">Create API key ↗</button></form>');$('#agent-form').onsubmit=async e=>{e.preventDefault();try{let f=new FormData(e.target),d=await api('/api/agents','POST',{name:f.get('name'),tools:f.getAll('tool')});openDialog('Your agent’s key.','SHOWN ONCE',`<p>Copy this key now. Relay stores only its hash. This key can submit scoped proposals; it cannot approve them.</p><div class="key" id="new-key">${esc(d.key)}</div><div class="notice">Keep it in an environment variable. Never put it in a frontend, repository, or public message.</div>`,'<button class="btn" id="copy-key">Copy key</button><button class="btn light" id="key-done">I saved it</button>');$('#copy-key').onclick=async()=>{try{await navigator.clipboard.writeText(d.key);toast('Key copied')}catch{toast('Select the key and copy it manually.')}};$('#key-done').onclick=()=>modal.close();await refresh();shell()}catch(err){toast(err.message)}}}
function revokeDialog(id){openDialog('Disconnect this agent?','REVOKE API KEY','<p>The key stops working immediately. Waiting and approved actions are blocked. An action already running cannot be recalled.</p>','<button class="btn light" id="keep">Keep connected</button><button class="btn danger" id="revoke-now">Revoke key</button>');$('#keep').onclick=()=>modal.close();$('#revoke-now').onclick=async()=>{try{await api('/api/agents/'+id+'/revoke','POST');modal.close();await refresh();shell();toast('Key revoked')}catch(e){toast(e.message)}}}
boot();setInterval(async()=>{if(!user||document.hidden||modal.open||document.activeElement?.matches('input,textarea,select'))return;try{await refresh();if(page==='inbox')shell()}catch{}},4000);
